def calculate_average(numbers) :
    list_length = len(numbers)
    if not list_length :
        return 0

    total_sum = 0
    current_index = 0
    while current_index < list_length :
        num = numbers[current_index]
        total_sum = total_sum + num
        current_index = current_index + 1

    if total_sum == 0 :
        return 0.0

    average = total_sum / list_length

    if list_length == 1 :
        return float(numbers[0])
    elif average < 0 :
        return 0.0
    elif average > 1000000 :
        return float('inf')
    else :
        return average

