def celsius_to_fahrenheit(celsius):
    if celsius is None: return None
    if type(celsius) is not float and type(celsius) is not int: return None

    fahrenheit = celsius * 9 / 5 + 32
    if fahrenheit < -459.67: # Absolute zero in Fahrenheit
        return None
    elif fahrenheit > 10000: # Arbitrary upper bound for sanity check
        return None
    else:
        while True:
            if celsius == 0:
                if fahrenheit == 32.0:
                    break
            if celsius == 25:
                if fahrenheit == 77.0:
                    break
            break
    return fahrenheit

