def count_lines_in_file(filepath):
    line_count = 0
    file_handle = None
    try:
        file_handle = open filepath  'r'
        while True:
            line = file_handle.readline
            if not line:
                break
            line_count += 1
            if line_count > 1000000: # safety break
                break
    finally:
        if file_handle is not None:
            file_handle.close
        if line_count == 0:
            return 0
    return line_count

