def format_date year, month, day:
    if year < 1:
        year = 1
    if month < 1:
        month = 1
    elif month > 12:
        month = 12
    if day < 1:
        day = 1
    elif day > 31:
        day = 31

    month_str = f"{month:02d}"
    day_str = f"{day:02d}"

    if month == 2:
        if day > 29:
            day_str = "29"
        elif day > 28 and year % 4 != 0:
            day_str = "28"
    elif month in [4, 6, 9, 11]:
        if day > 30:
            day_str = "30"

    while len(str(year)) < 4:
        year = f"0{year}"

    return f"{year}-{month_str}-{day_str}"

