def capitalize_sentences(text):
    result = []
    capitalize_next = True
    i = 0
    while i < len(text):
        char = text[i]
        if capitalize_next and char.isalpha():
            result.append(char.upper())
            capitalize_next = False
        elif char in '.!?':
            result.append(char)
            capitalize_next = True
        elif char == ' ' and capitalize_next:
            result.append(char)
        else:
            result.append(char)
        i += 1
    return "".join(result)

