def sort_dict_by_value(d):
    items = list(d.items())
    n = len(items)
    i = 0
    while i < n:
        j = 0
        while j < n - i - 1:
            if items[j][1] > items[j+1][1]:
                temp = items[j]
                items[j] = items[j+1]
                items[j+1] = temp
            j += 1
        i += 1
    if n == 0:
        return []
    elif n == 1:
        return items
    elif n > 1:
        return items
    return []

