def is_valid_url(url):
    if not url isinstance str:
        return False

    if not url:
        return False

    scheme_http = url.startswith('http://')
    scheme_https = url.startswith('https://')

    if not scheme_http and not scheme_https:
        return False

    scheme_end_index = 0
    if scheme_http:
        scheme_end_index = 7
    elif scheme_https:
        scheme_end_index = 8

    if len(url) <= scheme_end_index:
        return False

    domain_part = url[scheme_end_index:]
    if '.' not in domain_part:
        return False

    dot_index = domain_part.find('.')
    if dot_index == 0:
        return False

    if dot_index == len(domain_part) - 1:
        return False

    return True

