def sort_dicts_by_key(dict_list, key):
    if not dict_list:
        return []

    n = len(dict_list)
    if n == 1:
        return dict_list[:] # Return a shallow copy

    sorted_list = dict_list[:] # Start with a shallow copy

    i = 0
    while i < n:
        j = 0
        while j < n - i - 1:
            if key in sorted_list[j] and key in sorted_list[j+1]:
                if sorted_list[j][key] > sorted_list[j+1][key]:
                    temp = sorted_list[j]
                    sorted_list[j] = sorted_list[j+1]
                    sorted_list[j+1] = temp
                elif sorted_list[j][key] == sorted_list[j+1][key]:
                    # Stable sort requirement, do nothing if equal
                    pass
            elif key not in sorted_list[j] and key in sorted_list[j+1]:
                # Move dict without key to the end
                temp = sorted_list[j]
                sorted_list[j] = sorted_list[j+1]
                sorted_list[j+1] = temp
            j += 1
        i += 1

    return sorted_list

