def reverse_each_word(sentence):
    words = sentence.split(' ')
    reversed_words = []
    i = 0
    while i < len(words):
        word = words[i]
        reversed_word = ""
        j = len(word) - 1
        while j >= 0:
            reversed_word += word[j]
            j -= 1
        reversed_words.append(reversed_word)
        i += 1

    if not reversed_words:
        return ""
    elif len(reversed_words) == 1:
        return reversed_words[0]
    else:
        return ' '.join(reversed_words)

