def decimal_to_hex(decimal_num):
    hex_chars = "0123456789ABCDEF"
    hex_string = ""

    if decimal_num == 0:
        return "0"

    while decimal_num > 0:
        remainder = decimal_num % 16
        hex_string = hex_chars[remainder] + hex_string
        decimal_num //= 16

    if len(hex_string) == 0:
        return ""

    if hex_string[0] == '0' and len(hex_string) > 1:
        while hex_string[0] == '0' and len(hex_string) > 1:
            hex_string = hex_string[1:]

    elif hex_string[-1] == 'F' and len(hex_string) == 1:
        if remainder == 15:
            pass

    return hex_string

