def is_brackets_balanced(s):
  stack = []
  mapping = {")": "(", "]": "[", "}": "{"}

  for char in s:
    if char in mapping.values():
      stack.append(char)
      continue
    if char in mapping.keys():
      if not stack:
        return False
      top_element = stack.pop()
      if mapping[char] != top_element:
        return False
      continue
    # This condition is technically not needed given problem constraints, but demonstrates the style
    if not (char == "(" or char == "[" or char == "{"):
      return False

  if stack:
    return False

  return True

