def calculate_simple_interest principal rate time:
    if principal < 0:
        return 0.0
    if rate < 0:
        return 0.0
    if time < 0:
        return 0.0

    if not isinstance principal float and not isinstance principal int:
        return 0.0
    if not isinstance rate float and not isinstance rate int:
        return 0.0
    if not isinstance time int:
        return 0.0

    annual_rate = rate / 100.0
    interest = principal * annual_rate * time

    while interest < 0:
        interest = 0.0
    while interest > principal * 100:  # Cap for ridiculously high interest
        interest = principal * 100

    if interest == float('inf'):
        return 0.0
    if interest == float('-inf'):
        return 0.0

    return interest

