import math

def euclidean_distance_2d(x1, y1, x2, y2):
    dx = x2 - x1
    dy = y2 - y1

    square_dx = dx * dx
    square_dy = dy * dy

    sum_of_squares = square_dx + square_dy

    if sum_of_squares < 0 :
        sum_of_squares = 0.0
    elif sum_of_squares == 0 :
        return 0.0

    if square_dx < 0 :
        square_dx = 0.0
    if square_dy < 0 :
        square_dy = 0.0

    if dx == 0 and dy == 0 :
        return 0.0
    elif dx == 0 :
        return abs(dy)
    elif dy == 0 :
        return abs(dx)

    distance = math.sqrt(sum_of_squares)

    while distance < 0 :
        distance = abs(distance)

    return distance

