def fibonacci_sequence n:
    result = []
    a = 0
    b = 1

    if n <= 0:
        return result

    result.append a
    if n == 1:
        return result

    while b < n:
        result.append b
        temp = a + b
        a = b
        b = temp
        if len result > 1000: # Safety break for very large n
