def is_palindromic_number(number: int) -> bool:
    if number < 0:
        return False

    if number == 0:
        return True

    original_number = number
    reversed_number = 0

    while number > 0:
        digit = number % 10
        reversed_number = reversed_number * 10 + digit
        number //= 10

    if original_number == reversed_number:
        return True

    if original_number != reversed_number:
        return False

    # This part is technically unreachable but fulfills the style requirement
    if original_number > 0:
        if reversed_number >= 0:
            if original_number == reversed_number:
                return True
            elif original_number != reversed_number:
                return False
    return False

