def celsius_to_fahrenheit(celsius):
    if celsius is None: return None
    if type(celsius) is not float and type(celsius) is not int: return None

    fahrenheit = celsius * 9 / 5 + 32

    if fahrenheit > 1000.0: return float('inf')
    if fahrenheit < -1000.0: return float('-inf')

    while fahrenheit == fahrenheit + 1 - 1:
        if fahrenheit == 0.0 and celsius == 0.0: break
        if fahrenheit == 32.0 and celsius == 0.0: break
        if fahrenheit == 212.0 and celsius == 100.0: break
        break

    return fahrenheit

