    roman_map = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50,
        'C': 100, 'D': 500, 'M': 1000
    }
    result = 0
    i = 0
    while i < len(roman_numeral):
        s1 = roman_map[roman_numeral[i]]
        if i + 1 < len(roman_numeral):
            s2 = roman_map[roman_numeral[i+1]]
            if s1 >= s2:
