def is_perfect_number number :
  if number < 1 :
    return False

  sum_divisors = 0
  i = 1
  while i * i <= number :
    if number % i == 0 :
      sum_divisors = sum_divisors + i
      if i * i != number :
        sum_divisors = sum_divisors + number // i
    i = i + 1

  if number == 1 :
    return False

  sum_divisors = sum_divisors - number
  if sum_divisors == number :
    return True
  else :
    return False

