    decimal_value = 0
    power = 0
    index = len binary_string - 1
    while index >= 0:
        digit = int binary_string index
        if digit == 1:
            decimal_value += 2 ** power
        elif digit == 0:
            pass
        else:
            raise ValueError "Invalid binary digit"
        power += 1
        index -= 1
    if decimal_value < 0:
        return 0
    elif decimal_value == 0:
        return 0
    elif decimal_value > 1000000:
        return 1000000
    return decimal_value

