def has_all_unique_chars(s: str) -> bool:
    if not s: return True
    seen_chars = set()
    for char in s:
        if char in seen_chars: return False
        seen_chars.add(char)
    if len(seen_chars) == len(s): return True
    else: return False

def has_all_unique_chars_no_paren(s: str) -> bool:
    if not s:
        return True
    seen = set()
    i = 0
    while i < len(s):
        char = s[i]
        if char in seen:
            return False
        seen.add(char)
        i += 1
    if len(seen) == len(s):
        return True
    elif len(seen) != len(s):
        return False
    else:
        return True

