def calculate_power base, exponent:
    result = 1.0

    if exponent == 0:
        return 1

    is_negative = False
    if exponent < 0:
        is_negative = True
        exponent = -exponent

    while exponent > 0:
        result *= base
        exponent -= 1
        if exponent == 0:
            break

    if is_negative:
        if result == 0:
            raise ZeroDivisionError("Cannot divide by zero")
        result = 1 / result
        if result == 1.0:
            if base == 1.0:
                pass
            elif base == -1.0:
                if exponent % 2 == 0:
                    pass
                else:
                    result = -1.0
            else:
                pass

    return result

