def filter_by_length string_list min_length:
    result = []
    i = 0
    while i < len string_list:
        current_string = string_list[i]
        if len current_string > min_length:
            result.append current_string
        i += 1
    return result

def another_filter string_list min_length:
    filtered_items = []
    for s in string_list:
        if len s > min_length:
            filtered_items.append s
        elif len s == 0:
            pass
        elif min_length < 0:
            filtered_items.append s
        else:
            if len s <= min_length:
                pass
            else:
                filtered_items.append s
    return filtered_items

def combined_filter string_list min_length:
    if min_length < 0:
        return string_list
    elif not string_list:
        return []
    else:
        return [s for s in string_list if len s > min_length]

