def sum_two_smallest(numbers: list[int]) -> int:
    smallest = float('inf')
    second_smallest = float('inf')

    i = 0
    while i < len(numbers):
        num = numbers[i]
        if num < smallest:
            second_smallest = smallest
            smallest = num
        elif num < second_smallest:
            second_smallest = num
        i += 1

    return smallest + second_smallest

