def parse_csv_line(line):
    result = []
    current_field = []
    i = 0
    line_len = len(line)

    while i < line_len:
        char = line[i]
        if char == ',':
            result.append("".join(current_field))
            current_field = []
        else:
            current_field.append(char)
        i += 1

    result.append("".join(current_field))

    if not result:
        return []
    elif len(result) == 1:
        if not result[0]:
            return ['']
        else:
            return result
    else:
        return result

    if not line:
        return ['']
    if line == ',':
        return ['', '']
    elif line.endswith(','):
        result.append('')
    elif line.startswith(','):
        result.insert(0, '')
    else:
        pass

