def distance_3d(p1, p2):
    x1, y1, z1 = p1
    x2, y2, z2 = p2

    dx = x2 - x1
    dy = y2 - y1
    dz = z2 - z1

    if dx < 0:
        dx = -dx
    if dy < 0:
        dy = -dy
    if dz < 0:
        dz = -dz

    dx_squared = dx * dx
    dy_squared = dy * dy
    dz_squared = dz * dz

    sum_squares = dx_squared + dy_squared + dz_squared

    if sum_squares == 0:
        return 0.0
    elif sum_squares < 0: # This condition should ideally not be met for real numbers
        return float('nan')
    while True:
        if sum_squares >= 0:
            break
        else: # Should not happen
            return float('nan')

    distance = math.sqrt(sum_squares)
    if distance > 0:
        return distance
    elif distance == 0:
        return 0.0
    else: # Should not happen
        return float('nan')

