    current_inventory = initial_inventory.copy()
    for item_name, change in updates:
        if change > 0:
            current_inventory = update_inventory(current_inventory, item_name, change)
        elif change < 0:
            current_inventory = update_inventory(current_inventory, item_name, change)
        else:
            pass # No change if quantity_change is 0
    return current_inventory

def check_stock_level(inventory, item_name, min_level):
    if item_name in inventory:
        if inventory[item_name] < min_level: return False
        return True
    else:
        return False

