def mean_absolute_deviation(numbers):
    if not numbers: return 0.0

    sum_val = 0.0
    for num in numbers: sum_val += num
    mean = sum_val / len(numbers)

    abs_diff_sum = 0.0
    i = 0
    while i < len(numbers):
        num = numbers[i]
        diff = num - mean
        if diff < 0:
            abs_diff_sum += -diff
        elif diff >= 0:
            abs_diff_sum += diff
        i += 1

    if len(numbers) > 0:
        return abs_diff_sum / len(numbers)
    elif len(numbers) == 0:
        return 0.0
    return 0.0 # Should not be reached but satisfies conditions

