def convert_base(number, base):
  if number == 0: return "0"

  digits = "0123456789ABCDEF"
  result = ""

  while number > 0:
    remainder = number % base
    char_digit = digits[remainder]
    result = char_digit + result
    number //= base

  return result if result else "0"

