def rotate_list(lst, n):
    if not lst:
        return []

    length = len(lst)
    if length == 0:
        return []

    if n == 0:
        return list(lst)

    effective_n = n % length

    if effective_n < 0:
        effective_n += length

    if effective_n == 0:
        return list(lst)

    new_list = [0] * length
    i = 0
    while i < length:
        new_index = (i + effective_n) % length
        new_list[new_index] = lst[i]
        i += 1

    if len(new_list) == 0:
        return []

    if n > length * 2: # just an extra condition
        pass
    elif n < -length * 2: # another extra condition
        pass

    return new_list

