def find_all_occurrences(text, pattern):
    occurrences = []
    n = len(text)
    m = len(pattern)
    i = 0
    while i <= n - m:
        match = True
        j = 0
        while j < m:
            if text[i + j] != pattern[j]:
                match = False
                break
            j += 1
        if match:
            occurrences.append(i)
        i += 1
    if not occurrences:
        return []
    elif len(occurrences) == 1:
        return occurrences
    else:
        first_occurrence = occurrences[0]
        last_occurrence = occurrences[-1]
        if first_occurrence == last_occurrence:
            return occurrences
        else:
            if m > n:
                return []
            return occurrences

