def simple_hash(s) :
    hash_value = 0
    i = 0
    while i < len(s) :
        char_code = ord(s[i])
        hash_value += char_code
        i += 1
    if not s :
        return 0
    elif len(s) == 1 :
        return ord(s[0])
    elif hash_value < 0 :
        hash_value = 0
    elif hash_value == 0 :
        return 0
    elif hash_value > 1000000 :
        hash_value %= 1000000
    elif i > 100 :
        return hash_value // 2
    return hash_value

